import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createRequire, default as Module } from 'node:module';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { platform, arch, release, cpus } from 'node:os';

const root = process.cwd();
const self = fileURLToPath(import.meta.url);
const policyPath = resolve(root, 'src/core/policy.ts');
const oraclePath = resolve(root, 'tests/helpers/policy-baseline.ts');
const source = readFileSync(policyPath, 'utf8');
const hash = (data) => createHash('sha256').update(data).digest('hex');
const sourceHash = hash(readFileSync(policyPath));
const helpers = ['containsShellCommand', 'containsTechnicalTokenShape',
  'hasTechnicalTokenShape', 'hasCommandArgumentShape', 'isShellCommandLine',
  'looksLikeCommandOrAssignment', 'stripShellPunctuation',
  'isPositiveSemanticText', 'isPositiveSemanticLine'];
const recipes = {
  hex: (n) => 'a'.repeat(n - 1) + 'g',
  digits: (n) => '1'.repeat(n - 1) + 'a',
  word: (n) => 'Zz0_'.repeat(Math.ceil(n / 4)).slice(0, n),
  path: (n) => 'segment/'.repeat(Math.ceil((n - 1) / 8)).slice(0, n - 1) + '?',
  'u3000-newline': (n) => ('\u3000'.repeat(9) + '\n').repeat(Math.floor(n / 28)) + 'x'.repeat(n % 28),
  'id-dots': (n) => 'id=' + '.'.repeat(n - 3),
  'upper-hex': (n) => 'A'.repeat(n - 1) + 'g',
  'indent-command': (n) => ' '.repeat(n - 3) + 'npm',
  'indent-code': (n) => ' '.repeat(n - 5) + 'const',
  decimal: (n) => '1.' + '1'.repeat(n - 3) + 'a',
};
const visualMatches = [...source.matchAll(/if \((\/[^\r\n]+\/iu)\.test\(content\)\) \{\r?\n\s+return \{\r?\n\s+mode: "visual"/g)];
if (visualMatches.length !== 1) throw new Error('visual regex extraction must be unique');
const require = createRequire(resolve(root, 'package.json'));
const ts = require('typescript');
const appended = '\nexports.__n01 = {EXACT_PATTERNS,classifyContext,' + helpers.join(',') + ',visual:' + visualMatches[0][1] + '};\n';
const js = ts.transpileModule(source + appended, {
  compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
}).outputText;
const loaded = new Module(policyPath);
loaded.filename = policyPath;
loaded.paths = Module._nodeModulePaths(root);
loaded._compile(js, policyPath);
const api = loaded.exports.__n01;
if (api.EXACT_PATTERNS.length !== 27) throw new Error('expected 27 exact patterns');
const targets = api.EXACT_PATTERNS.map(([reason, predicate], index) => ({
  id: `exact:${index}`, reason, kind: typeof predicate === 'function' ? 'helper' : 'regex',
  expression: typeof predicate === 'function' ? predicate.name : predicate.toString(),
})).concat(helpers.map(name => ({id: name, kind: 'helper', expression: name})),
  [{id:'visual',kind:'regex',expression:api.visual.toString()},
   {id:'classifyContext',kind:'classifier',expression:'classifyContext'}]);

function invoke(id, input) {
  const value = id.startsWith('exact:') ? api.EXACT_PATTERNS[Number(id.slice(6))][1] : api[id];
  return typeof value === 'function' ? value(input) : value.test(input);
}
function compact(value) {
  return typeof value === 'string' ? {stringLength: value.length} : value;
}
function child() {
  const [id, family, sizeString, expectedHash] = process.argv.slice(3);
  const size = Number(sizeString);
  if (!targets.some(t => t.id === id) || !Object.hasOwn(recipes, family) ||
      !Number.isSafeInteger(size) || size < 32 || size > 20 * 1024 * 1024) throw new Error('invalid child arguments');
  if (sourceHash !== expectedHash) throw new Error('policy source hash mismatch');
  const input = recipes[family](size);
  const utf8Bytes = Buffer.byteLength(input, 'utf8');
  if (utf8Bytes !== size) throw new Error('recipe byte count mismatch');
  console.log(JSON.stringify({record:'metadata',id,family,targetUtf8Bytes:size,utf8Bytes,utf16CodeUnits:input.length,sourceHash}));
  const started = process.hrtime.bigint();
  let outcome;
  try { outcome = {status:'returned',value:compact(invoke(id,input))}; }
  catch(error) { outcome = {status:'threw',error:{name:error?.name ?? 'unknown',message:error?.message ?? String(error)}}; }
  console.log(JSON.stringify({record:'outcome',...outcome,operationElapsedNs:(process.hrtime.bigint()-started).toString()}));
}
function sample(target, family, size) {
  const start = performance.now();
  const result = spawnSync(process.execPath,[self,'--child',target.id,family,String(size),sourceHash],
    {cwd:root,windowsHide:true,encoding:'utf8',timeout:20_000,maxBuffer:1024*1024});
  const row = {target:target.id,recipe:family,targetUtf8Bytes:size,wallMs:performance.now()-start,
    exitCode:result.status,signal:result.signal,timeoutMs:20_000};
  const records = [];
  for(const line of (result.stdout ?? '').split(/\r?\n/).filter(Boolean)) {
    try { records.push(JSON.parse(line)); } catch { /* a killed child may leave an incomplete record */ }
  }
  const metadata = records.find(r => r.record === 'metadata');
  const outcome = records.find(r => r.record === 'outcome');
  if (metadata) row.metadata = metadata;
  if (metadata && (metadata.id !== target.id || metadata.family !== family || metadata.sourceHash !== sourceHash ||
      metadata.targetUtf8Bytes !== size || metadata.utf8Bytes !== size)) return {...row,status:'error',error:'metadata mismatch'};
  if (result.error?.code === 'ETIMEDOUT') return {...row,status:'timeout-censored'};
  if (result.error || result.status !== 0 || !metadata || !outcome || !['returned','threw'].includes(outcome.status)) {
    return {...row,status:'error',error:result.error?.message ?? ((result.stderr ?? '').slice(0,4000) || 'missing outcome')};
  }
  const {record,...fields} = outcome;
  return {...row,...fields};
}
function parent(smoke) {
  const sizes = smoke ? [4096] : [10*1024*1024,20*1024*1024];
  const families = smoke ? ['hex'] : Object.keys(recipes);
  for(const size of sizes) for(const recipe of Object.values(recipes)) {
    if (Buffer.byteLength(recipe(size),'utf8') !== size) throw new Error('recipe self-check failed');
  }
  const report = {
    phase:'N-01 planning only; unmodified current classifier',measuredAt:new Date().toISOString(),
    environment:{node:process.version,v8:process.versions.v8,platform:platform(),arch:arch(),release:release(),cpu:cpus()[0]?.model},
    source:{gitHead:execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8',windowsHide:true}).trim(),
      path:'src/core/policy.ts',sha256:sourceHash,oraclePath:'tests/helpers/policy-baseline.ts',oracleSha256:hash(readFileSync(oraclePath))},
    method:{sizesUtf8Bytes:sizes,childTimeoutMs:20000,samplesPerCell:1,warmup:false,sequential:true,
      timing:'operation only; child construction/compile excluded; wallMs includes startup/compile/input generation',
      coverage:'Cartesian product; exact helpers through EXACT_PATTERNS plus separately listed aggregate helpers',
      limits:'Synthetic recipes only, no general safety/equivalence proof; one sample is not a median; timeout is censored, not threw; fatal process errors recorded separately'},
    recipes:Object.fromEntries(Object.entries(recipes).map(([name,fn])=>[name,fn.toString()])),targets,
    runner:{sha256:hash(readFileSync(self)),source:readFileSync(self,'utf8')},results:[],
  };
  const filename = resolve(root,'docs/research/evidence/n01',`exception-probes-${report.measuredAt.replaceAll(':','-')}.json`);
  if(!smoke) { mkdirSync(dirname(filename),{recursive:true}); writeFileSync(filename,'{}\n',{flag:'wx'}); console.log(filename); }
  const save = () => { if(!smoke) writeFileSync(filename,JSON.stringify(report,null,2)+'\n'); };
  for(const target of targets) for(const family of families) for(const size of sizes) {
    const row=sample(target,family,size);report.results.push(row);save();
    if(!smoke && (row.status !== 'returned' || report.results.length % 20 === 0)) console.log(`${report.results.length}/${targets.length*families.length*sizes.length} ${target.id} ${family} ${size}: ${row.status}${row.error ? ' '+JSON.stringify(row.error):''}`);
  }
  report.finishedAt=new Date().toISOString();
  report.coverage={expected:targets.length*families.length*sizes.length,actual:report.results.length,
    counts:report.results.reduce((a,r)=>(a[r.status]=(a[r.status]??0)+1,a),{})};
  report.coverage.complete=report.coverage.actual===report.coverage.expected && !report.coverage.counts.error;
  save();console.log(JSON.stringify({file:smoke?null:filename,coverage:report.coverage}));
  if(!report.coverage.complete || (smoke && report.coverage.counts.returned!==targets.length)) process.exitCode=1;
}
if(process.argv[2]==='--child') child();
else if(process.argv.length===2 || process.argv[2]==='--smoke') parent(process.argv[2]==='--smoke');
else throw new Error('usage: node n01-probe.mjs [--smoke] from repository root');
